package com.brainserve.onboarding.tasks.application.service;
import com.brainserve.onboarding.common.security.TenantPrincipal; import com.brainserve.onboarding.tasks.infrastructure.persistence.TaskRepository; import java.util.UUID; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Component;
@Component("taskAuthorization") public class TaskAuthorization {private final TaskRepository tasks;public TaskAuthorization(TaskRepository tasks){this.tasks=tasks;}public boolean isInternalAssignee(Authentication authentication,UUID taskId){Object principal=authentication.getPrincipal();if(!(principal instanceof TenantPrincipal p))return false;return tasks.findByOrganizationIdAndId(p.organizationId(),taskId).map(t->p.userId().equals(t.getAssignedUserId())&&"INTERNAL".equals(t.getAssignedUserType())).orElse(false);}}
